import { PIPELINE_EVENT_TYPES } from "./events.js";
import { INSTRUCTION_VARIABLES } from "./instructions.js";
import type { Policy } from "./policy.types.js";
import { conditionLines, decisionText } from "./reference-parts.js";

const code = (s: string) => `\`${s}\``;
const cell = (s: string) => s.replaceAll("|", "\\|");

const INTRO = [
  "---",
  "title: Pipeline policies",
  "description: The default policies of the event pipeline, in evaluation order, with what each listens to, when it matches, what it decides and the instruction it gives.",
  "---",
  "",
  "<!-- Generated by `pnpm --filter @outstaff/office run docs:pipeline`. Do not edit by hand. -->",
  "",
  "These are the policies the office runs when the team changes nothing, in evaluation order ([decision 0018](/decisions/0018-pipeline-only/)). Every policy that listens to an event is evaluated, and every one that matches contributes its decision. [What outstaff does on its own](/concepts/automation/) explains the events and the decisions.",
  "",
  "A team changes a policy under [`pipeline.policies.<id>`](/reference/team-yaml/#pipelinepolicies) in team.yaml: `enabled: false` turns it off (it stays in the trace), `instruction` replaces the instruction of a wake or the note of an act, and `when` narrows it, so both its own condition and the team's must hold.",
];

/** One row of the overview: the policy, what it listens to and what it decides. */
const row = (p: Policy): string =>
  `| [${code(p.id)}](#${p.id}) | ${p.on.map(code).join(", ")} | ${cell(decisionText(p.decide))} |`;

function switchLines(p: Policy, switches: Readonly<Record<string, string>>): string[] {
  const path = switches[p.id];
  return path ? ["", `On only while ${code(`policies.${path}`)} is on.`] : [];
}

const whenLines = (p: Policy): string[] =>
  p.when ? ["", "When:", "", ...conditionLines(p.when)] : ["", "When: always."];

function instructionLines(p: Policy): string[] {
  if (!p.instruction) {
    return [];
  }

  const wakes = "wake" in p.decide || ("act" in p.decide && p.decide.act.wake);
  const label = wakes ? "Instruction:" : "Note posted with the change:";
  return ["", label, "", "```text", p.instruction, "```"];
}

function policySection(p: Policy, switches: Readonly<Record<string, string>>): string[] {
  return [
    "",
    `### ${p.id}`,
    "",
    p.summary,
    "",
    `Listens to ${p.on.map(code).join(", ")}. Decides: ${decisionText(p.decide)}.`,
    ...switchLines(p, switches),
    ...whenLines(p),
    ...instructionLines(p),
  ];
}

/** Markdown for the pipeline policies reference page, generated from the default policies. */
export function renderPolicyReference(
  policies: readonly Policy[],
  switches: Readonly<Record<string, string>>,
): string {
  return [
    ...INTRO,
    "",
    "## Overview",
    "",
    "| Policy | Listens to | Decides |",
    "| --- | --- | --- |",
    ...policies.map(row),
    "",
    "## Policies",
    ...policies.flatMap((p) => policySection(p, switches)),
    "",
    "## Events",
    "",
    "Every event the pipeline decides on. A policy's `on` lists some of them.",
    "",
    ...PIPELINE_EVENT_TYPES.map((t) => `- ${code(t)}`),
    "",
    "## Instruction variables",
    "",
    "An instruction or note may use these placeholders, written `{{name}}`. One the event does not have is empty, and an unknown name in `pipeline.policies.<id>.instruction` keeps the default instruction, with a warning in the office log.",
    "",
    ...INSTRUCTION_VARIABLES.map((v) => `- ${code(v)}`),
    "",
  ].join("\n");
}
